  'notice.noSession.body': { en: 'Check the link with whoever is running the session, or scan the code on the screen in the room to ask a question.', es: 'Comprueba el enlace con quien dirige la sesión, o escanea el código de la pantalla de la sala para hacer una pregunta.', ko: '세션을 운영하는 분과 링크를 확인하거나, 회의실 화면의 코드를 스캔해 질문하세요.' },
  'notice.denied.tab': { en: 'Not available', es: 'No disponible', ko: '이용할 수 없음' },
  'notice.denied.title': { en: 'This view is for QA Facilitators', es: 'Esta vista es para los facilitadores de preguntas', ko: '이 화면은 질문 진행자용입니다' },
  'notice.denied.body': { en: 'Sign in with an account listed as a QA Facilitator, or scan the code on the screen in the room to ask a question.', es: 'Inicia sesión con una cuenta que figure como facilitador/a de preguntas, o escanea el código de la pantalla de la sala para hacer una pregunta.', ko: '질문 진행자로 등록된 계정으로 로그인하거나, 회의실 화면의 코드를 스캔해 질문하세요.' },

