  'mail.weeklyOff': { en: 'Turn this report off on the Admin page → Health &amp; testing.', es: 'Desactiva este informe en la página de administración → Estado y pruebas.', ko: '이 보고는 관리 페이지 → 상태 및 테스트에서 끌 수 있습니다.' },
  'mail.alertSubject': { en: 'Question Desk: {subject}', es: 'Question Desk: {subject}', ko: 'Question Desk: {subject}' },
  'mail.alertGroupingFailing': { en: 'Question grouping is failing', es: 'La agrupación de preguntas está fallando', ko: '질문 묶기가 실패하고 있습니다' },
  'mail.alertGroupingBody': { en: '<p>Questions are arriving but have not been grouped or translated for {n} runs in a row. QA Facilitators still see every question, ungrouped.</p><p><strong>Last error:</strong> {why}</p><p>Open the Admin page → Health and run a health check. A 404 usually means the Gemini model name ({model}) was retired; a 400 or 403 usually means the API key.</p>', es: '<p>Están llegando preguntas, pero no se han agrupado ni traducido en {n} ejecuciones seguidas. Los facilitadores de preguntas siguen viéndolas todas, sin agrupar.</p><p><strong>Último error:</strong> {why}</p><p>Abre la página de administración → Estado y haz una comprobación de estado. Un 404 suele significar que el modelo de Gemini ({model}) fue retirado; un 400 o 403 suele ser la clave de API.</p>', ko: '<p>질문은 들어오고 있지만 {n}회 연속으로 묶이거나 번역되지 않았습니다. 질문 진행자에게는 모든 질문이 묶이지 않은 채로 계속 보입니다.</p><p><strong>마지막 오류:</strong> {why}</p><p>관리 페이지 → 상태에서 상태 점검을 실행하세요. 404는 보통 Gemini 모델 이름({model})이 중단된 경우이고, 400이나 403은 보통 API 키 문제입니다.</p>' },
  'mail.alertGroupingRecovered': { en: 'Question grouping recovered', es: 'La agrupación de preguntas se recuperó', ko: '질문 묶기가 복구되었습니다' },
  'mail.alertGroupingRecoveredBody': { en: '<p>Grouping and translation are working again.</p>', es: '<p>La agrupación y la traducción vuelven a funcionar.</p>', ko: '<p>묶기와 번역이 다시 작동합니다.</p>' },

  'mail.linkAsk': { en: 'Ask a question', es: 'Hacer una pregunta', ko: '질문하기' },
  'mail.linkAskNote': { en: 'Anyone with this link can submit a question anonymously. If it says "Sorry, unable to open the file", open it in a private browsing window.', es: 'Cualquiera con este enlace puede enviar una pregunta de forma anónima. Si dice "Lo sentimos, no se puede abrir el archivo", ábrelo en una ventana de navegación privada.', ko: '이 링크가 있으면 누구나 익명으로 질문을 보낼 수 있습니다. "죄송합니다. 파일을 열 수 없습니다"가 나오면 시크릿 창에서 여세요.' },
  'mail.linkPresent': { en: 'Room screen', es: 'Pantalla de la sala', ko: '회의실 화면' },
  'mail.linkPresentNote': { en: 'Open on the projector — no sign-in needed. Anyone with this link can see the join code, so share it only with the people running the room. Use a private browsing window on the projector computer, so no Google sign-in gets in the way.', es: 'Ábrela en el proyector: no hace falta iniciar sesión. Cualquiera con este enlace puede ver el código de entrada, así que compártelo solo con quienes dirigen la sala. Usa una ventana de navegación privada en el ordenador del proyector, para que no se meta por medio ninguna sesión de Google.', ko: '프로젝터에서 여세요 — 로그인이 필요 없습니다. 이 링크가 있으면 참여 코드를 볼 수 있으니 회의실을 운영하는 분들에게만 공유하세요. 프로젝터 컴퓨터에서도 시크릿 창을 쓰면 Google 로그인이 끼어들지 않습니다.' },
  'mail.linkModerate': { en: 'QA Facilitator queue', es: 'Cola del facilitador de preguntas', ko: '질문 진행자 대기열' },
  'mail.linkModerateNote': { en: 'Questions grouped by topic. Requires signing in with an assigned {domain} account.', es: 'Preguntas agrupadas por tema. Hay que iniciar sesión con una cuenta {domain} asignada.', ko: '주제별로 묶인 질문입니다. 지정된 {domain} 계정으로 로그인해야 합니다.' },
  'mail.linksSessionSubject': { en: '{name} — Question Desk links', es: '{name} — enlaces de Question Desk', ko: '{name} — Question Desk 링크' },

