  'admin.sessions.groupsTheSessionsHeld': { en: 'Groups the sessions held at one event, such as a conference with several rooms.', es: 'Agrupa las sesiones que se celebran en un mismo evento, como una conferencia con varias salas.', ko: '여러 방에서 열리는 컨퍼런스처럼, 한 행사에서 열리는 세션들을 묶습니다.' },
  'admin.sessions.qaFacilitatorsForEvery': { en: 'QA Facilitators for every session in this event', es: 'Facilitadores de preguntas de todas las sesiones de este evento', ko: '이 행사의 모든 세션 질문 진행자' },
  'admin.sessions.theyCanRunThe': { en: 'They can run the queue for all of this event\'s sessions. Sessions can add more of their own. (Summaries go to the Session Summary Email Recipients on the People tab.)', es: 'Pueden dirigir la cola de todas las sesiones de este evento. Cada sesión puede añadir más. (Los resúmenes van a los destinatarios del resumen de la sesión, en la pestaña Personas.)', ko: '이 행사의 모든 세션 대기열을 운영할 수 있습니다. 세션마다 진행자를 더 추가할 수 있습니다. (요약은 사람 탭의 세션 요약 메일 수신자에게 갑니다.)' },
