  'admin.branding.oneLineOnThe': { en: 'One line on the landing page and participant page, e.g. "Thank you for joining us tonight."', es: 'Una línea en la página de inicio y en la del público, p. ej. "Gracias por acompañarnos esta noche."', ko: '시작 페이지와 참석자 페이지에 한 줄로 표시됩니다. 예: "오늘 함께해 주셔서 감사합니다."' },
  'admin.branding.websiteOrContactLine': { en: 'Website or contact line on every page and email.', es: 'Sitio web o línea de contacto en cada página y correo.', ko: '모든 페이지와 메일에 들어가는 웹사이트나 연락처 한 줄.' },
  'admin.branding.roomScreenBackgroundDark': { en: 'Room screen background — dark', es: 'Fondo de la pantalla de la sala — oscuro', ko: '회의실 화면 배경 — 어두운색' },
