  'admin.branding.removeLogo': { en: 'Remove logo', es: 'Quitar logotipo', ko: '로고 삭제' },
  'admin.branding.resizedInYourBrowser': { en: 'Resized in your browser before upload so pages stay fast on venue wifi. A wide logo on a transparent or white background works best.', es: 'Se reduce en tu navegador antes de subirlo para que las páginas sigan siendo rápidas con el wifi del recinto. Va mejor un logotipo ancho sobre fondo transparente o blanco.', ko: '행사장 와이파이에서도 페이지가 빠르도록 업로드 전에 브라우저에서 크기를 줄입니다. 투명하거나 흰 배경의 가로로 긴 로고가 가장 잘 맞습니다.' },
  'admin.activity.activityLog': { en: 'Activity log', es: 'Registro de actividad', ko: '활동 기록' },
  'admin.activity.actSearch.hint': { en: 'Search people, actions, sessions…', es: 'Busca personas, acciones, sesiones…', ko: '사람, 작업, 세션 검색…' },
