  'admin.health.healthCheck': { en: 'Health check', es: 'Comprobación de estado', ko: '상태 점검' },
  'admin.health.testsTheGeminiKey': { en: 'Tests the Gemini key and model, the every-minute trigger, the sheet, email quota and the app address. Admins are also emailed automatically if grouping fails 3 minutes in a row.', es: 'Prueba la clave y el modelo de Gemini, el activador de cada minuto, la hoja, la cuota de correo y la dirección de la aplicación. Además, se avisa por correo a los administradores si la agrupación falla 3 minutos seguidos.', ko: 'Gemini 키와 모델, 1분 트리거, 시트, 메일 한도, 앱 주소를 점검합니다. 묶기가 3분 연속 실패하면 관리자에게 자동으로 메일이 갑니다.' },
  'admin.health.runHealth': { en: 'Run health check', es: 'Hacer la comprobación', ko: '상태 점검 실행' },
  'admin.health.sgrouping': { en: 'Last grouping', es: 'Última agrupación', ko: '마지막 묶기' },
