  'admin.health.separateAddressesWithCommas': { en: 'Separate addresses with commas or new lines. Each person gets their own email.', es: 'Separa las direcciones con comas o saltos de línea. Cada persona recibe su propio correo.', ko: '주소는 쉼표나 줄바꿈으로 구분하세요. 각자에게 따로 메일이 갑니다.' },
