  'admin.dragOrUseTo': { en: 'Drag ⋮⋮ or use ▲ ▼ to change the order of sessions within an event.', es: 'Arrastra ⋮⋮ o usa ▲ ▼ para cambiar el orden de las sesiones dentro de un evento.', ko: '⋮⋮ 를 끌거나 ▲ ▼ 로 행사 안 세션 순서를 바꾸세요.' },
